// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (marked QUIRK) so a restructuring can't change them silently.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 2, pear: 3.5, tv: 60 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, string id, echoed items, total', async () => {
  const items = [{ sku: 'apple', qty: 3 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 6)
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
})

test('ids are distinct and sequential', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums multiple items', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 2 }, { sku: 'tv', qty: 1 }] })).json()
  assert.equal(order.total, 64)
})

test('total is floored to whole euros', async () => {
  const order = await (await post({ items: [{ sku: 'pear', qty: 1 }] })).json()
  assert.equal(order.total, 3)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 50 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount when raw total is over 100', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 51 }] })).json()
  assert.equal(order.total, 91) // 102 * 0.9 = 91.8 -> floored
  const big = await (await post({ items: [{ sku: 'tv', qty: 5 }] })).json()
  assert.equal(big.total, 270)
})

test('POST /orders rejects bad bodies with 400', async () => {
  for (const [body, raw] of [
    [{}], [{ items: [] }], [{ items: 'apple' }], [null, 'not json'],
  ]) {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns a created order', async () => {
  const created = await (await post({ items: [{ sku: 'tv', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('QUIRK: GET unknown order returns 200 with an error body, not 404', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  for (const [method, path] of [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/extra'],
    ['DELETE', '/orders/1'], ['PUT', '/orders'],
  ]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
